pub fn many_m_n<I, E, F>(
  min: usize,
  max: usize,
  parser: F,
) -> impl Parser<I, Output = Vec<<F as Parser<I>>::Output>, Error = E>
where
  I: Clone + InputLength,
  F: Parser<I, Error = E>,
  E: ParseError<I>,
{
  ManyMN { parser, min, max }
