            })));
          }

          res = OM::Output::combine(res, value, |res, o| (self.g)(res, o));
          input = tail;
        }
        Err(Err::Error(err)) => {
          if count < self.min {
            return Err(Err::Error(OM::Error::map(err, |err| {
              <F as Parser<I>>::Error::append(input, ErrorKind::ManyMN, err)
            })));
          } else {
            break;
          }
        }
        Err(e) => return Err(e),
      }
    }

    Ok((input, res))
  }
}

